-- Functions
CREATE OR REPLACE FUNCTION public.activate_subscription(p_store_id text, p_plan text, p_duration_months integer DEFAULT 1, p_custom_price numeric DEFAULT NULL::numeric, p_keep_expiration boolean DEFAULT false, p_manual_expiration timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_expires_at TIMESTAMPTZ;
BEGIN
  -- Verificar autorización de Superadmin o service_role
  IF auth.role() != 'service_role' AND COALESCE((auth.jwt()->'app_metadata'->>'role'), '') != 'super_admin' THEN
    RAISE EXCEPTION 'No autorizado. Solo super administradores pueden realizar esta acción.';
  END IF;

  -- Si el plan es semilla (gratis), no se establece expiración
  IF p_plan = 'semilla' THEN
    UPDATE public.stores
    SET
      plan                 = p_plan,
      plan_expires_at      = NULL,
      subscription_status  = 'trial',
      plan_duration_months = NULL,
      custom_price         = NULL
    WHERE id = p_store_id;
  ELSE
    -- Determinar la nueva fecha de vencimiento
    IF p_manual_expiration IS NOT NULL THEN
      -- Se establece una fecha manual explícita
      UPDATE public.stores
      SET
        plan                 = p_plan,
        plan_expires_at      = p_manual_expiration,
        subscription_status  = 'active',
        custom_price         = p_custom_price,
        cancelled_at         = NULL,
        cancel_reason        = NULL
      WHERE id = p_store_id;
    ELSIF p_keep_expiration THEN
      -- Se mantiene la fecha de vencimiento actual de la tienda
      UPDATE public.stores
      SET
        plan                 = p_plan,
        subscription_status  = 'active',
        custom_price         = p_custom_price,
        cancelled_at         = NULL,
        cancel_reason        = NULL
      WHERE id = p_store_id;
    ELSE
      -- Se extiende sumando meses desde NOW()
      v_expires_at := NOW() + (p_duration_months || ' months')::INTERVAL;
      UPDATE public.stores
      SET
        plan                 = p_plan,
        plan_expires_at      = v_expires_at,
        subscription_status  = 'active',
        plan_duration_months = p_duration_months,
        custom_price         = p_custom_price,
        cancelled_at         = NULL,
        cancel_reason        = NULL
      WHERE id = p_store_id;
    END IF;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_subscription(p_store_id text, p_plan text, p_duration_months integer DEFAULT 1, p_custom_price numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_expires_at TIMESTAMPTZ;
  v_referred_price NUMERIC;
BEGIN
  -- Verificar autorización
  IF auth.role() != 'service_role' AND COALESCE((auth.jwt()->'app_metadata'->>'role'), '') != 'super_admin' THEN
    RAISE EXCEPTION 'No autorizado. Solo super administradores pueden realizar esta acción.';
  END IF;

  -- Si el plan es semilla (gratis), no se establece expiración
  IF p_plan = 'semilla' THEN
    UPDATE public.stores
    SET
      plan                 = p_plan,
      plan_expires_at      = NULL,
      subscription_status  = 'trial',
      plan_duration_months = NULL,
      custom_price         = NULL
    WHERE id = p_store_id;
  ELSE
    v_expires_at := NOW() + (p_duration_months || ' months')::INTERVAL;
    UPDATE public.stores
    SET
      plan                 = p_plan,
      plan_expires_at      = v_expires_at,
      subscription_status  = 'active',
      plan_duration_months = p_duration_months,
      custom_price         = p_custom_price,
      cancelled_at         = NULL,
      cancel_reason        = NULL
    WHERE id = p_store_id;

    -- AUTOMATIZACIÓN DE REFERIDOS:
    -- Calcular precio efectivo pagado por el referido
    v_referred_price := COALESCE(p_custom_price, public.get_plan_price(p_plan));
    
    -- Procesar la recompensa de tiempo si el plan adquirido es de pago
    IF v_referred_price > 0 THEN
      PERFORM public.process_referral_reward(p_store_id, p_plan, v_referred_price);
    END IF;
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.activate_subscription_with_invite(p_store_id text, p_invite_token text)
 RETURNS TABLE(plan text, duration_value integer, duration_unit text, custom_price numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_invite RECORD;
  v_expires_at TIMESTAMPTZ;
  v_subscription_status TEXT;
  v_plan_duration_months INT;
BEGIN
  -- 1. Buscar y bloquear la fila del invite para evitar condiciones de carrera
  SELECT * INTO v_invite
  FROM public.invites
  WHERE token = p_invite_token AND used = false AND expires_at > NOW()
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'El enlace de invitación no es válido o ya fue utilizado.';
  END IF;

  -- 2. Marcar el invite como usado
  UPDATE public.invites
  SET used = true
  WHERE token = p_invite_token;

  -- 3. Activar la suscripción de la tienda
  IF v_invite.plan = 'semilla' THEN
    UPDATE public.stores
    SET
      plan                 = v_invite.plan,
      plan_expires_at      = NULL,
      subscription_status  = 'trial',
      plan_duration_months = NULL,
      custom_price         = NULL
    WHERE id = p_store_id;
  ELSE
    -- Calcular expiración y estado según la unidad
    IF v_invite.duration_unit = 'days' THEN
      v_expires_at := NOW() + (v_invite.duration_value || ' days')::INTERVAL;
      v_subscription_status := 'trial';
      v_plan_duration_months := 0;
    ELSE
      v_expires_at := NOW() + (v_invite.duration_value || ' months')::INTERVAL;
      v_subscription_status := 'active';
      v_plan_duration_months := v_invite.duration_value;
    END IF;

    UPDATE public.stores
    SET
      plan                 = v_invite.plan,
      plan_expires_at      = v_expires_at,
      subscription_status  = v_subscription_status,
      plan_duration_months = v_plan_duration_months,
      custom_price         = v_invite.custom_price,
      cancelled_at         = NULL,
      cancel_reason        = NULL
    WHERE id = p_store_id;
  END IF;

  RETURN QUERY 
  SELECT 
    v_invite.plan::TEXT, 
    v_invite.duration_value::INT, 
    v_invite.duration_unit::TEXT, 
    v_invite.custom_price::NUMERIC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cancel_subscription(p_store_id text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  -- Verificar que el ejecutor sea service_role o un usuario autenticado con rol super_admin en app_metadata
  IF auth.role() != 'service_role' AND COALESCE((auth.jwt()->'app_metadata'->>'role'), '') != 'super_admin' THEN
    RAISE EXCEPTION 'No autorizado. Solo super administradores pueden realizar esta acción.';
  END IF;

  UPDATE public.stores
  SET
    plan                = 'semilla',
    subscription_status = 'cancelled',
    cancelled_at        = NOW(),
    cancel_reason       = p_reason,
    plan_expires_at     = NOW()  -- vence inmediatamente
  WHERE id = p_store_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_invite(p_token text)
 RETURNS TABLE(plan text, expires_at timestamp with time zone, duration_months integer, duration_value integer, duration_unit text, custom_price numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    i.plan::TEXT, 
    i.expires_at, 
    i.duration_months::INT, 
    i.duration_value::INT, 
    i.duration_unit::TEXT, 
    i.custom_price::NUMERIC
  FROM public.invites i
  WHERE i.token = p_token 
    AND i.used = false 
    AND i.expires_at > NOW();
END;
$function$
;

CREATE OR REPLACE FUNCTION public.degrade_expired_plans()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_count INT;
BEGIN
  UPDATE stores
  SET
    plan                = 'semilla',
    subscription_status = 'expired'
  WHERE
    subscription_status = 'active'
    AND plan_expires_at IS NOT NULL
    AND plan_expires_at < NOW();

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.extend_subscription(p_store_id text, p_months_to_add integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_current_expires TIMESTAMPTZ;
BEGIN
  -- Verificar que el ejecutor sea service_role o un usuario autenticado con rol super_admin en app_metadata
  IF auth.role() != 'service_role' AND COALESCE((auth.jwt()->'app_metadata'->>'role'), '') != 'super_admin' THEN
    RAISE EXCEPTION 'No autorizado. Solo super administradores pueden realizar esta acción.';
  END IF;

  SELECT plan_expires_at INTO v_current_expires FROM public.stores WHERE id = p_store_id;

  -- Si ya expiró, extiende desde ahora; si no, extiende desde la fecha actual
  UPDATE public.stores
  SET
    plan_expires_at     = GREATEST(v_current_expires, NOW()) + (p_months_to_add || ' months')::INTERVAL,
    subscription_status = 'active',
    cancelled_at        = NULL,
    cancel_reason       = NULL
  WHERE id = p_store_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_store(store_slug text, page_limit integer DEFAULT 36, page_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  store_row record;
  store_plan text;
  days_expired int;
  effective_limit int;
  effective_model text;
  effective_banner text;
  total_prod_count int;
  actual_limit int;
  result jsonb;
BEGIN
  SELECT * INTO store_row FROM stores WHERE slug = store_slug AND active = true LIMIT 1;
  IF store_row IS NULL THEN
    RETURN NULL;
  END IF;

  IF store_row.plan_expires_at IS NOT NULL AND store_row.plan_expires_at < now() THEN
    days_expired := date_part('day', now() - store_row.plan_expires_at)::int;
  ELSE
    days_expired := -1;
  END IF;

  IF store_row.plan = 'semilla' THEN
    store_plan := 'semilla';
  ELSIF days_expired > 3 THEN
    store_plan := 'semilla';
  ELSE
    store_plan := store_row.plan;
  END IF;

  IF store_plan = 'semilla' THEN
    effective_limit := 20;
  ELSIF store_plan = 'emprendedor' THEN
    effective_limit := 100;
  ELSIF store_plan = 'pro' THEN
    effective_limit := 300;
  ELSIF store_plan = 'ilimitado' THEN
    effective_limit := 1000;
  ELSE
    effective_limit := 1000;
  END IF;

  effective_model := COALESCE(store_row.model, 'minimalista');

  -- Combinar las imágenes de los banners si existe el arreglo banners
  IF store_row.banners IS NOT NULL AND array_length(store_row.banners, 1) > 0 THEN
    effective_banner := array_to_string(store_row.banners, '|||');
  ELSE
    effective_banner := store_row.banner_image;
  END IF;

  -- Contar el total de productos visibles para este store (hasta el límite de su plan)
  SELECT LEAST(count(*), effective_limit) INTO total_prod_count
  FROM products
  WHERE store_id = store_row.id AND visible = true;

  -- Calcular el límite real para este lote
  actual_limit := LEAST(COALESCE(page_limit, 36), effective_limit);

  SELECT jsonb_build_object(
    'id', store_row.id,
    'slug', store_row.slug,
    'name', store_row.name,
    'phone', store_row.phone,
    'country_code', store_row.country_code,
    'logo', store_row.logo,
    'brand_color', store_row.brand_color,
    'bg_color', store_row.bg_color,
    'text_color', store_row.text_color,
    'card_bg', store_row.card_bg,
    'accent_color', store_row.accent_color,
    'border_radius', store_row.border_radius,
    'img_shape', store_row.img_shape,
    'is_dark', store_row.is_dark,
    'banner_image', effective_banner,
    'banner_title', store_row.banner_title,
    'banner_style', COALESCE(store_row.banner_style, 'direct'),
    'niche', COALESCE(store_row.niche, 'general'),
    'catalog_typography', COALESCE(store_row.catalog_typography, 'sans'),
    'card_style', COALESCE(store_row.card_style, 'standard'),
    'plan', store_plan,
    'model', effective_model,
    'active', store_row.active,
    'is_published', store_row.is_published,
    'created_at', store_row.created_at,
    'whatsapp_clicks', COALESCE(store_row.whatsapp_clicks, 0),
    'views', COALESCE(store_row.views, 0),
    'price_filter_enabled', store_row.price_filter_enabled,
    'libro_reclamaciones_activo', store_row.libro_reclamaciones_activo,
    'empresa_ruc', store_row.empresa_ruc,
    'empresa_razon_social', store_row.empresa_razon_social,
    'empresa_direccion', store_row.empresa_direccion,
    'total_products_count', COALESCE(total_prod_count, 0)
  ) || jsonb_build_object(
    'plan_expires_at', store_row.plan_expires_at,
    'subscription_status', store_row.subscription_status,
    'cancelled_at', store_row.cancelled_at,
    'cancel_reason', store_row.cancel_reason,
    'plan_duration_months', store_row.plan_duration_months,
    'bio_description', store_row.bio_description,
    'bio_links_enabled', COALESCE(store_row.bio_links_enabled, false),
    'bio_banner', store_row.bio_banner,
    'bio_logo', store_row.bio_logo,
    'bio_theme', store_row.bio_theme,
    'bio_typography', store_row.bio_typography,
    'bio_show_catalog_button', store_row.bio_show_catalog_button,
    'bio_button_style', store_row.bio_button_style,
    'bio_button_color', store_row.bio_button_color,
    'bio_button_text_color', store_row.bio_button_text_color,
    'bio_bg_image', store_row.bio_bg_image,
    'bio_bg_color', store_row.bio_bg_color,
    'quick_links', (
      CASE WHEN store_plan = 'semilla' THEN
          COALESCE((SELECT jsonb_agg(value) FROM (SELECT value FROM jsonb_array_elements(COALESCE(store_row.quick_links, '[]'::jsonb)) LIMIT 3) t), '[]'::jsonb)
      ELSE
          COALESCE(store_row.quick_links, '[]'::jsonb)
      END
    ),
    'location_lat', store_row.location_lat,
    'location_lng', store_row.location_lng,
    'location_address', store_row.location_address,
    'banner_tagline', store_row.banner_tagline,
    'banner_bottom_tag', store_row.banner_bottom_tag,
    'show_dizi_branding', store_row.show_dizi_branding,
    'promo_bar_enabled', store_row.promo_bar_enabled,
    'promo_bar_text', store_row.promo_bar_text,
    'promo_bar_action_type', store_row.promo_bar_action_type,
    'promo_bar_action_value', store_row.promo_bar_action_value,
    'promo_bar_bg_color', store_row.promo_bar_bg_color,
    'promo_bar_text_color', store_row.promo_bar_text_color,
    'promo_bar_is_marquee', store_row.promo_bar_is_marquee,
    'categories', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', c.id,
        'name', c.name,
        'product_count', (
          SELECT count(*)::int FROM products p 
          WHERE p.store_id = store_row.id AND p.category_id = c.id AND p.visible = true
        )
      )), '[]'::jsonb)
      FROM categories c
      WHERE c.store_id = store_row.id
    ),
    'products', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id,
        'name', name,
        'price', price,
        'category_id', category_id,
        'image', image,
        'description', description,
        'is_on_sale', is_on_sale,
        'original_price', original_price,
        'visible', visible,
        'is_sample', is_sample,
        'sort_order', sort_order,
        'variations', COALESCE(variations, '[]'::jsonb),
        'created_at', created_at
      )), '[]'::jsonb)
      FROM (
        SELECT * FROM products
        WHERE store_id = store_row.id AND visible = true
        ORDER BY sort_order ASC NULLS LAST, created_at DESC
        LIMIT actual_limit
        OFFSET COALESCE(page_offset, 0)
      ) p
    )
  ) INTO result;

  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_public_store_products(p_store_slug text, p_page_offset integer DEFAULT 0, p_page_limit integer DEFAULT 24, p_category_id text DEFAULT NULL::text, p_search_query text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_store_row record;
  v_effective_limit int;
  result jsonb;
BEGIN
  SELECT id, plan, plan_expires_at INTO v_store_row FROM stores WHERE slug = p_store_slug AND active = true LIMIT 1;
  IF v_store_row IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  IF v_store_row.plan = 'semilla' THEN
    v_effective_limit := 20;
  ELSIF v_store_row.plan = 'emprendedor' THEN
    v_effective_limit := 100;
  ELSIF v_store_row.plan = 'pro' THEN
    v_effective_limit := 300;
  ELSE
    v_effective_limit := 1000;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', p.id,
    'name', p.name,
    'price', p.price,
    'category_id', p.category_id,
    'image', p.image,
    'description', p.description,
    'is_on_sale', p.is_on_sale,
    'original_price', p.original_price,
    'visible', p.visible,
    'is_sample', p.is_sample,
    'sort_order', p.sort_order,
    'variations', COALESCE(p.variations, '[]'::jsonb),
    'created_at', p.created_at
  )), '[]'::jsonb) INTO result
  FROM (
    SELECT * FROM products
    WHERE store_id = v_store_row.id 
      AND visible = true
      AND (p_category_id IS NULL OR p_category_id = '' OR p_category_id = 'all' OR products.category_id = p_category_id)
      AND (
        p_search_query IS NULL 
        OR p_search_query = '' 
        OR products.name ILIKE '%' || p_search_query || '%'
        OR COALESCE(products.description, '') ILIKE '%' || p_search_query || '%'
      )
    ORDER BY sort_order ASC NULLS LAST, created_at DESC
    LIMIT LEAST(COALESCE(p_page_limit, 24), v_effective_limit)
    OFFSET COALESCE(p_page_offset, 0)
  ) p;

  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_store_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'stores' THEN
    NEW.updated_at = NOW();
    RETURN NEW;
  ELSIF TG_TABLE_NAME = 'products' THEN
    IF TG_OP = 'DELETE' THEN
      UPDATE public.stores SET updated_at = NOW() WHERE id = OLD.store_id;
      RETURN OLD;
    ELSE
      UPDATE public.stores SET updated_at = NOW() WHERE id = NEW.store_id;
      RETURN NEW;
    END IF;
  END IF;
  RETURN NULL;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_user_sync_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- Si se intenta registrar con rol 'super_admin' en user_metadata, forzar a 'store_owner'
    IF COALESCE(NEW.raw_user_meta_data->>'role', '') = 'super_admin' THEN
      NEW.raw_user_meta_data := NEW.raw_user_meta_data || jsonb_build_object('role', 'store_owner');
    END IF;
    NEW.raw_app_meta_data := NEW.raw_app_meta_data || jsonb_build_object('role', COALESCE(NEW.raw_user_meta_data->>'role', 'store_owner'));
    
  ELSIF TG_OP = 'UPDATE' THEN
    -- Bloquear auto-promoción si un cliente intenta cambiar su propio user_metadata a 'super_admin'
    IF NEW.raw_user_meta_data->>'role' = 'super_admin' 
       AND (OLD.raw_user_meta_data->>'role' IS NULL OR OLD.raw_user_meta_data->>'role' != 'super_admin') 
       AND COALESCE(OLD.raw_app_meta_data->>'role', '') != 'super_admin' 
       AND COALESCE(NEW.raw_app_meta_data->>'role', '') != 'super_admin' THEN
      NEW.raw_user_meta_data := NEW.raw_user_meta_data || jsonb_build_object('role', 'store_owner');
    END IF;
    
    -- Sincronizar el app_metadata con el user_metadata si el usuario no es super_admin
    -- Pero si en NEW.raw_app_meta_data ya viene 'super_admin' (por actualización administrativa), respetarlo
    IF COALESCE(NEW.raw_app_meta_data->>'role', '') != 'super_admin' AND COALESCE(OLD.raw_app_meta_data->>'role', '') != 'super_admin' THEN
      NEW.raw_app_meta_data := NEW.raw_app_meta_data || jsonb_build_object('role', COALESCE(NEW.raw_user_meta_data->>'role', 'store_owner'));
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.increment_store_egress(p_store_id text, p_bytes bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
