CREATE OR REPLACE FUNCTION public.insert_reclamacion(p_tenant_id text, p_consumidor_nombre text, p_consumidor_tipo_doc text, p_consumidor_num_doc text, p_consumidor_domicilio text, p_consumidor_telefono text, p_consumidor_email text, p_es_menor_edad boolean, p_tutor_nombre text, p_tutor_num_doc text, p_bien_descripcion text, p_bien_monto numeric, p_tipo text, p_descripcion text, p_pedido_consumidor text)
 RETURNS TABLE(id uuid, numero_correlativo integer, fecha timestamp with time zone, empresa_nombre text, empresa_ruc text, empresa_direccion text, empresa_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_next_num      INTEGER;
  v_emp_nombre    TEXT;
  v_emp_ruc       TEXT;
  v_emp_dir       TEXT;
  v_emp_url       TEXT;
  v_id            UUID;
  v_fecha         TIMESTAMPTZ;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(p_tenant_id));
 
  SELECT COALESCE(MAX(r.numero_correlativo), 0) + 1
    INTO v_next_num
    FROM reclamaciones r
   WHERE r.tenant_id = p_tenant_id;
 
  SELECT
    COALESCE(s.empresa_razon_social, s.name),
    s.empresa_ruc,
    s.empresa_direccion,
    concat('dizi.pe/t/', s.slug)
  INTO v_emp_nombre, v_emp_ruc, v_emp_dir, v_emp_url
  FROM stores s
  WHERE s.id = p_tenant_id;
 
  INSERT INTO reclamaciones (
    tenant_id, numero_correlativo,
    empresa_nombre, empresa_ruc, empresa_direccion, empresa_url,
    consumidor_nombre, consumidor_tipo_doc, consumidor_num_doc,
    consumidor_domicilio, consumidor_telefono, consumidor_email,
    es_menor_edad, tutor_nombre, tutor_num_doc,
    bien_descripcion, bien_monto,
    tipo, descripcion, pedido_consumidor
  ) VALUES (
    p_tenant_id, v_next_num,
    v_emp_nombre, v_emp_ruc, v_emp_dir, v_emp_url,
    p_consumidor_nombre, p_consumidor_tipo_doc, p_consumidor_num_doc,
    p_consumidor_domicilio, p_consumidor_telefono, p_consumidor_email,
    p_es_menor_edad, p_tutor_nombre, p_tutor_num_doc,
    p_bien_descripcion, p_bien_monto,
    p_tipo, p_descripcion, p_pedido_consumidor
  )
  RETURNING reclamaciones.id, reclamaciones.fecha
    INTO v_id, v_fecha;
 
  RETURN QUERY
    SELECT v_id, v_next_num, v_fecha, v_emp_nombre, v_emp_ruc, v_emp_dir, v_emp_url;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.process_referral_reward(p_referred_store_id text, p_referred_plan text, p_referred_price numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_referrer_slug TEXT;
  v_referred_slug TEXT;
  v_rewarded BOOLEAN;
  v_referrer_id TEXT;
  v_referrer_plan TEXT;
  v_referrer_expires TIMESTAMPTZ;
BEGIN
  -- 1. Obtener datos de la tienda referida
  SELECT referred_by, referral_rewarded, slug 
  INTO v_referrer_slug, v_rewarded, v_referred_slug
  FROM public.stores 
  WHERE id = p_referred_store_id;

  -- 2. Validaciones de salida temprana
  -- - No tiene referente
  -- - Ya fue premiado antes
  -- - Es una auto-referencia (intento de fraude)
  IF v_referrer_slug IS NULL OR v_referrer_slug = '' OR v_rewarded = TRUE OR v_referrer_slug = v_referred_slug THEN
    RETURN;
  END IF;

  -- 3. Buscar datos de la tienda referente por su slug
  SELECT id, plan, plan_expires_at
  INTO v_referrer_id, v_referrer_plan, v_referrer_expires
  FROM public.stores 
  WHERE slug = v_referrer_slug;

  -- Si el referente no existe, no procesamos nada
  IF v_referrer_id IS NULL THEN
    RETURN;
  END IF;

  -- 4. Procesar recompensa de TIEMPO para el REFERENTE (30 días de suscripción gratis)
  IF v_referrer_plan = 'semilla' THEN
    -- Si el referente estaba en plan Semilla (gratuito), se le hace un upgrade al plan del referido por 30 días
    UPDATE public.stores
    SET 
      plan = p_referred_plan,
      subscription_status = 'active',
      plan_expires_at = NOW() + INTERVAL '30 days',
      plan_duration_months = 1,
      custom_price = NULL
    WHERE id = v_referrer_id;
  ELSE
    -- Si ya tenía un plan de pago, se le extienden 30 días adicionales a su expiración actual
    UPDATE public.stores
    SET plan_expires_at = COALESCE(
      CASE 
        WHEN plan_expires_at < NOW() THEN NOW() 
        ELSE plan_expires_at 
      END,
      NOW()
    ) + INTERVAL '30 days'
    WHERE id = v_referrer_id;
  END IF;

  -- 5. Procesar recompensa de TIEMPO para el REFERIDO (tienda recién activada)
  -- Se le extienden 30 días adicionales a la vigencia del plan que acaba de adquirir
  UPDATE public.stores
  SET plan_expires_at = COALESCE(
    CASE 
      WHEN plan_expires_at < NOW() THEN NOW() 
      ELSE plan_expires_at 
    END,
    NOW()
  ) + INTERVAL '30 days'
  WHERE id = p_referred_store_id;

  -- 6. Marcar la tienda referida como premiada para evitar doble asignación
  UPDATE public.stores 
  SET referral_rewarded = TRUE 
  WHERE id = p_referred_store_id;
  
END;
$function$
;

CREATE OR REPLACE FUNCTION public.set_invite_expires_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.expires_at IS NULL THEN
    -- El invite (el link) expira en 30 días por defecto, independientemente de la duración del plan
    NEW.expires_at := NOW() + INTERVAL '30 days';
  END IF;
  RETURN NEW;
END;
$function$
;

-- Triggers
DROP TRIGGER IF EXISTS trg_invite_expires_at ON public.invites;
CREATE TRIGGER trg_invite_expires_at BEFORE INSERT ON public.invites FOR EACH ROW EXECUTE FUNCTION set_invite_expires_at();

DROP TRIGGER IF EXISTS trg_products_touch_store ON public.products;
CREATE TRIGGER trg_products_touch_store AFTER INSERT ON public.products FOR EACH ROW EXECUTE FUNCTION handle_store_touch_updated_at();

DROP TRIGGER IF EXISTS trg_products_touch_store ON public.products;
CREATE TRIGGER trg_products_touch_store AFTER DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION handle_store_touch_updated_at();

DROP TRIGGER IF EXISTS trg_products_touch_store ON public.products;
CREATE TRIGGER trg_products_touch_store AFTER UPDATE ON public.products FOR EACH ROW EXECUTE FUNCTION handle_store_touch_updated_at();

DROP TRIGGER IF EXISTS trg_stores_touch_updated_at ON public.stores;
CREATE TRIGGER trg_stores_touch_updated_at BEFORE UPDATE ON public.stores FOR EACH ROW EXECUTE FUNCTION handle_store_touch_updated_at();

DROP TRIGGER IF EXISTS trg_user_sync_role ON auth.users;
CREATE TRIGGER trg_user_sync_role
  BEFORE INSERT OR UPDATE ON auth.users
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_user_sync_role();

